fast_pseudocode:
# DO NOT DO THIS for register-heavy pointwise kernels:
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 2048}, num_warps=8),
        triton.Config({'XBLOCK': 1024}, num_warps=8),
        triton.Config({'XBLOCK': 256},  num_warps=4),
        triton.Config({'XBLOCK': 128},  num_warps=4),
    ],
    key=['xnumel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    # autotune selected XBLOCK=256, 76 regs/thread → 37.5% theoretical occupancy
    ...

grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](...)  # XBLOCK removed from call site

